<script lang="ts">import {onMount} from 'svelte';export let records:any[]=[];export let themes:any[]=[];let query='';let kinds:string[]=[];let selectedThemes:string[]=[];let limit=60;
$: types=[...new Set(records.map(r=>r.kind))].filter(k=>k!=='Story').sort();
$: filtered=records.filter(r=>r.kind!=='Story'&&(!kinds.length||kinds.includes(r.kind))&&(!selectedThemes.length||selectedThemes.some(t=>r.themeIds?.includes(t)))&&(!query||[r.name,...r.aliases||[]].join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase()))).sort((a,b)=>a.name.localeCompare(b.name,'en-NZ'));
function url(){const p=new URLSearchParams();if(query)p.set('q',query);kinds.forEach(k=>p.append('kind',k));selectedThemes.forEach(t=>p.append('theme',t));history.replaceState(null,'','?'+p);limit=60}
function toggle(k:string){kinds=kinds.includes(k)?kinds.filter(x=>x!==k):[...kinds,k];url()}
function theme(t:string){selectedThemes=selectedThemes.includes(t)?selectedThemes.filter(x=>x!==t):[...selectedThemes,t];url()}
onMount(()=>{const p=new URLSearchParams(location.search);query=p.get('q')||'';kinds=p.getAll('kind');selectedThemes=p.getAll('theme')});</script>
<label>Find a name<input type="search" bind:value={query} on:input={url} placeholder="Name or other known name" style="display:block;width:100%;margin:12px 0 22px"/></label><div class="chips" aria-label="Entry types">{#each types as k}<button aria-pressed={kinds.includes(k)} on:click={()=>toggle(k)}>{k}</button>{/each}</div><details><summary>Filter by theme</summary><div class="chips">{#each themes as t}<button aria-pressed={selectedThemes.includes(t.id)} on:click={()=>theme(t.id)}>{t.title}</button>{/each}</div></details><p aria-live="polite">{filtered.length} entries <button on:click={()=>{query='';kinds=[];selectedThemes=[];url()}}>Clear filters</button></p><div class="cards">{#each filtered.slice(0,limit) as r}<article class="card"><small>{r.kind}</small><a class="title" href={r.url}>{r.name}</a><p>{(r.description||r.story?.[0]||'').slice(0,180)}{(r.description||r.story?.[0]||'').length>180?'…':''}</p></article>{/each}</div>{#if !filtered.length}<p class="empty">No matching entries. Try another name or clear the filters.</p>{/if}{#if filtered.length>limit}<button style="margin-top:25px" on:click={()=>limit+=60}>Show more entries</button>{/if}
